var items = pdfa(html, ".module-items&&.module-item");
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = pdfh(item, ".module-item-title&&Text");
  var img = pd(item, ".module-item-pic img&&data-original||.module-item-pic img&&src", MY_URL);
  var url = pd(item, ".module-item-title&&href", MY_URL);
  var desc = pdfh(item, ".module-item-note&&Text");
  d.push({
    title: title,
    desc: desc,
    pic_url: img + '@Referer=' + MY_URL,
    url: url,
    col_type: 'movie_3'
  });
}
setResult(d);

