detail_find_rule:
js:
var templateLazy = function () {
  var html = request(input);
  var match = html.match(/player_aaaa\s*=\s*({[\s\S]*?})\s*;?\s*<\/script>/i);
  if (!match) throw new Error('模板未解析播放器配置，请按真实站点适配');
  var config = JSON.parse(match[1]);
  var media = config && typeof config.url === 'string' ? config.url : '';
  if (media.indexOf('//') === 0) media = (input.indexOf('https:') === 0 ? 'https:' : 'http:') + media;
  if (!/^https?:\/\//i.test(media)) throw new Error('模板未取得真实媒体地址，不能返回原网页冒充播放');
  return media;
};
var d = [];
var html = request(MY_URL);
var title = pdfh(html, ".video-info-header h1&&Text");
var cover = pd(html, ".video-cover img&&src", MY_URL);
var intro = pdfh(html, ".video-info-main&&Text");

// 1. 顶部基础卡片
d.push({
  title: title,
  desc: intro,
  pic_url: cover + '@Referer=' + MY_URL,
  url: MY_URL,
  col_type: 'pic_1_card'
});

// 2. 线路 Tab 提取
var tabs = pdfa(html, ".module-tab-items-box&&.module-tab-item");
var playlists = pdfa(html, ".module-list&&.module-blocklist");

for (var tabIndex = 0; tabIndex < tabs.length; tabIndex++) {
  var tabName = pdfh(tabs[tabIndex], "Text") || ('线路 ' + (tabIndex + 1));
  d.push({
    title: '【' + tabName + '】',
    col_type: 'text_1'
  });
  var currentList = playlists[tabIndex] ? pdfa(playlists[tabIndex], "a") : [];
  for (var epIndex = 0; epIndex < currentList.length; epIndex++) {
    var ep = currentList[epIndex];
    var epTitle = pdfh(ep, "Text");
    var epUrl = pd(ep, "a&&href", MY_URL);
    d.push({
      title: epTitle,
      url: epUrl + '@lazyRule=.js:(' + templateLazy.toString() + ')()',
      col_type: 'text_3'
    });
  }
}
setResult(d);
